/**
 * session-learner.ts — 诊断会话学习器
 *
 * P2-20b: 对标 Hermes 后台审查代理模式。
 *
 * Hermes 模式：
 *   每次对话结束后，派生独立 LLM 审查对话质量，学习：
 *     1. 用户偏好（记忆 → MEMORY.md）
 *     2. 工作流改进（技能 → 创建/修补 skill）
 *     3. 用户挫败信号（"不要再做 X" → 一等技能信号）
 *
 * Synova 适配：
 *   每次诊断完成后，轻量级审查：
 *     1. 采纳模式学习——哪些建议被采纳/拒绝，按组织特征聚类
 *     2. 术语学习——用户使用的术语 vs 引擎使用的术语
 *     3. 效果关联——采纳的建议 vs 后续诊断变化
 *     4. 挫败检测——诊断报告与实际偏差过大的信号
 *
 * 三层学习：
 *   Layer 1 (本模块): 单次诊断后即时学习 → 本地术语表更新 + 采纳偏好记录
 *   Layer 2 (action-tracking.ts EvolutionSignal): 3+ 次诊断 → 组织级自校准提案
 *   Layer 3 (后续): 跨组织 → 联邦进化聚合
 */
export interface SessionLearning {
    learningId: string;
    diagnosisId: string;
    orgId: string;
    teamId: string;
    /** 采纳偏好：按维度的采纳率 */
    adoptionPreferences: Record<string, {
        adopted: number;
        rejected: number;
        rate: number;
    }>;
    /** 术语学习：用户表述 vs 引擎术语 */
    terminologyMappings: Array<{
        userTerm: string;
        engineTerm: string;
        confidence: number;
    }>;
    /** 效果信号：采纳建议后，对应维度在下一次诊断中的变化 */
    effectSignals: Array<{
        actionId: string;
        dimension: string;
        preScore?: number;
        postScore?: number;
        delta?: number;
        interpretation: 'improved' | 'worsened' | 'unchanged' | 'insufficient_data';
    }>;
    /** 挫败信号：报告与实际偏差过大的标记 */
    frustrationSignals: Array<{
        dimension: string;
        reportedAccuracy: number;
        signal: string;
    }>;
    /** 推荐：基于本次学习，下次诊断的建议 */
    recommendations: string[];
    generatedAt: string;
}
export interface LearningPattern {
    patternId: string;
    orgId: string;
    /** 模式类型 */
    patternType: 'adoption_correlation' | 'terminology_shift' | 'effect_correlation' | 'frustration_pattern';
    /** 模式描述（人类可读） */
    finding: string;
    /** 置信度 */
    confidence: number;
    /** 样本量（基于多少次诊断） */
    sampleSize: number;
    /** 范围 */
    scope: 'org_internal' | 'cross_org_potential';
    /** 相关维度 */
    dimensions: string[];
    /** 生成时间 */
    discoveredAt: string;
}
/**
 * 学习术语映射：当用户用不同的词描述同一概念时，记录下来。
 * 下次诊断时，引擎使用用户术语以提升可读性。
 */
export declare function learnTerminology(orgId: string, mappings: Array<{
    userTerm: string;
    engineTerm: string;
}>): void;
/** 获取组织的术语映射表 */
export declare function getOrgTerminology(orgId: string): Record<string, string>;
/** 将引擎术语翻译为用户术语 */
export declare function translateToUserTerms(orgId: string, text: string): string;
/** 从诊断结果生成会话学习 */
export declare function generateSessionLearning(diagnosisId: string, orgId: string, teamId: string, options?: {
    terminologyMappings?: Array<{
        userTerm: string;
        engineTerm: string;
        confidence: number;
    }>;
    effectSignals?: SessionLearning['effectSignals'];
    frustrationSignals?: SessionLearning['frustrationSignals'];
    previousScores?: Record<string, number>;
    currentScores?: Record<string, number>;
}): SessionLearning;
/**
 * 从 ≥3 次会话学习中提取跨诊断模式。
 * 对标 Hermes Curator 的周期性技能审查。
 */
export declare function discoverPatterns(orgId: string): LearningPattern[];
/** 获取组织已发现的模式 */
export declare function getOrgPatterns(orgId: string): LearningPattern[];
/** 清空所有存储（测试用） */
export declare function clearLearnerStore(): void;
